import Foundation

@main struct MailMonitoringChecks {
    static func main() throws {
        var calendar = Calendar(identifier:.gregorian); calendar.timeZone = TimeZone(identifier:"Europe/London")!
        let now = ISO8601DateFormatter().date(from:"2026-10-06T10:00:00Z")!
        let accounts = [MailAccount(id:"a",title:"A"),MailAccount(id:"b",title:"B")]
        var state = try JSONDecoder().decode(MailIndexState.self,from:Data(#"{"windows":[]}"#.utf8))
        state.prepare(accounts:accounts,now:now,calendar:calendar)
        assert(state.monitor("a")!.start == now.addingTimeInterval(-48*3600))
        assert(state.windows.count == 62)
        // Finished historical cache remains intact across frequent refreshes.
        for i in state.windows.indices { state.windows[i].complete = true; state.windows[i].lastSuccess = now }
        let first = state.monitor("a")!
        let empty = MailBatch(messages:[],messageIDs:[],nextOffset:0,complete:true,errors:[])
        var snapshot = MailSnapshot(messages:[],accounts:accounts,errors:[])
        snapshot = state.apply(empty,to:first.id,snapshot:snapshot,now:now)
        state.prepare(accounts:accounts,now:now.addingTimeInterval(60),calendar:calendar)
        assert(state.monitor("a")!.start == now.addingTimeInterval(60-48*3600))
        assert(state.windows.allSatisfy(\.complete), "Polling must not reopen the month's history")
        let monitor = state.monitor("a")!
        _ = state.apply(MailBatch(messages:[],messageIDs:[1,2],nextOffset:1,complete:false,errors:[]),to:monitor.id,snapshot:snapshot,now:now)
        state = try JSONDecoder().decode(MailIndexState.self,from:JSONEncoder().encode(state))
        state.prepare(accounts:accounts,now:now.addingTimeInterval(3600),calendar:calendar)
        assert(state.monitor("a")!.end == monitor.end && state.monitor("a")!.offset == 1 && state.monitor("a")!.messageIDs == [1,2], "An interrupted arrival scan keeps its exact range and cursor")
        assert(state.windows.filter { !$0.complete }.count <= 2, "An hourly audit nominates at most one day per account")
        let background = state.background("a",now:now.addingTimeInterval(3600))!
        assert(state.background("a",now:now.addingTimeInterval(3660)) == nil)
        state.failed("a",detail:"timeout",now:now)
        assert(!state.available("a",now:now.addingTimeInterval(30)) && state.available("b",now:now))
        state.failed("a",detail:"timeout",now:now.addingTimeInterval(60))
        assert(!state.available("a",now:now.addingTimeInterval(179)) && state.available("a",now:now.addingTimeInterval(180)))
        state.resume()
        assert(state.available("a",now:now) && state.monitor("a")!.offset == 1)
        state.resetCursor(monitor.id)
        assert(state.monitor("a")!.offset == 0 && state.monitor("a")!.messageIDs == nil)
        assert(state.windows.first(where:{ $0.id == background.id }) != nil)
        state.prepare(accounts:[accounts[1]],now:now.addingTimeInterval(86400),calendar:calendar)
        assert(state.monitors!.allSatisfy { $0.accountID == "b" } && state.windows.allSatisfy { $0.accountID == "b" })
        var offline = MailIndexState()
        offline.prepare(accounts:accounts,now:now,calendar:calendar,lastCheck:now.addingTimeInterval(-40*86400))
        assert(offline.monitor("a")!.start == now.addingTimeInterval(-30*86400), "A known offline gap catches up once within cache retention")
        // Partial scans retain unseen cache rows; complete exact ranges reconcile
        // deletions while leaving older rows and the other account untouched.
        func message(_ id:Int,account:String,received:Date) throws -> MailMessage {
            let json:[String:Any] = ["id":account+":"+String(id),"accountID":account,"account":account,"messageID":id,"internetMessageID":"fixture\(id)@example.invalid","sender":"Fixture","subject":"Test","received":received.ISO8601Format(),"unread":true,"replied":false,"flagged":false]
            return try JSONDecoder().decode(MailMessage.self,from:JSONSerialization.data(withJSONObject:json))
        }
        var reconcile = MailIndexState(); reconcile.prepare(accounts:accounts,now:now,calendar:calendar)
        let kept = try message(1,account:"a",received:now.addingTimeInterval(-60))
        let removed = try message(2,account:"a",received:now.addingTimeInterval(-60))
        let older = try message(3,account:"a",received:now.addingTimeInterval(-3*86400))
        let other = try message(4,account:"b",received:now.addingTimeInterval(-60))
        let original = MailSnapshot(messages:[kept,removed,older,other],accounts:accounts,errors:[])
        let part = reconcile.apply(MailBatch(messages:[kept],messageIDs:[1,2],nextOffset:1,complete:false,errors:[]),to:reconcile.monitor("a")!.id,snapshot:original,now:now)
        assert(part.messages.count == 4)
        reconcile.resetCursor(reconcile.monitor("a")!.id)
        let end = reconcile.apply(MailBatch(messages:[kept],messageIDs:[1],nextOffset:1,complete:true,errors:[]),to:reconcile.monitor("a")!.id,snapshot:part,now:now)
        assert(Set(end.messages.map(\.id)) == ["a:1","a:3","b:4"])
        var late=MailIndexState(); late.prepare(accounts:accounts,now:now,calendar:calendar)
        let unseen=try message(5,account:"a",received:now.addingTimeInterval(-3*3600))
        let observed=late.apply(MailBatch(messages:[unseen],messageIDs:[5],nextOffset:1,complete:true,errors:[],retainedIDs:[1]),to:late.monitor("a")!.id,snapshot:original,now:now)
        assert(Set(observed.messages.map(\.id)) == ["a:1","a:3","a:5","b:4"], "Late delivery is added, verified known identities retained and vanished messages removed")
        var reviews=MailIndexState();reviews.discovered(now:now);reviews.prepare(accounts:accounts,now:now,calendar:calendar)
        _ = reviews.apply(empty,to:reviews.monitor("b")!.id,snapshot:original,now:now)
        reviews.failed("a",detail:"timeout",now:now)
        let mixed=MailReviewScope.capture(index:reviews,snapshot:original,excluded:[],since:now)
        assert(mixed.accountIDs == ["b"] && mixed.issues["a"] == "timeout" && mixed.pending,"Failed account must not block completed healthy arrival check")
        assert(mixed.permits("b",index:reviews,snapshot:original,excluded:[]) && !mixed.permits("a",index:reviews,snapshot:original,excluded:[]))
        assert(!mixed.permits("b",index:reviews,snapshot:original,excluded:["b"]),"Revoked account scope rejects captured review")
        let noAccount=MailSnapshot(messages:original.messages,accounts:[accounts[0]],errors:[])
        assert(!mixed.permits("b",index:reviews,snapshot:noAccount,excluded:[]),"Account removal invalidates a captured review even with retained cache")
        reviews.failed("a",detail:"second failure",now:now)
        assert(mixed.permits("b",index:reviews,snapshot:original,excluded:[]),"Unrelated account failure does not invalidate healthy lane")
        reviews.failed("b",detail:"body timeout",now:now)
        let afterBody=mixed.available(index:reviews,snapshot:original,excluded:[])
        assert(afterBody.accountIDs.isEmpty && afterBody.issues["b"] == "body timeout","Body failure narrows assessment without advancing that account")
        reviews.resume();_ = reviews.apply(empty,to:reviews.monitor("a")!.id,snapshot:original,now:now)
        let recoveredReview=MailReviewScope.capture(index:reviews,snapshot:original,excluded:[],since:now)
        assert(recoveredReview.accountIDs == ["a","b"],"Recovered arrival checks become eligible without resetting historical windows")
        let excludedReview=MailReviewScope.capture(index:reviews,snapshot:original,excluded:["a"],since:now)
        assert(excludedReview.accountIDs == ["b"] && !excludedReview.pending)
        let staleReview=MailReviewScope.capture(index:reviews,snapshot:original,excluded:[],since:now.addingTimeInterval(31))
        assert(staleReview.accountIDs.isEmpty && staleReview.issues.count == 2,"Old successful cache is not a fresh arrival receipt")
        reviews.discovered(error:"discovery timeout",now:now)
        let failedDiscovery=MailReviewScope.capture(index:reviews,snapshot:original,excluded:[],since:now)
        assert(failedDiscovery.discoveryFailed && failedDiscovery.accountIDs.isEmpty && !recoveredReview.permits("b",index:reviews,snapshot:original,excluded:[]))
        let oldIndex=try JSONDecoder().decode(MailIndexState.self,from:Data(#"{"windows":[]}"#.utf8))
        assert(MailReviewScope.capture(index:oldIndex,snapshot:original,excluded:[],since:now).accountIDs.isEmpty,"Legacy cache waits for first real source check")
        let roundtrip=try JSONDecoder().decode(MailIndexState.self,from:JSONEncoder().encode(reviews))
        assert(roundtrip.discoveryChecked == now && roundtrip.discoveryError == "discovery timeout")
        // Heartbeat analyses independently collected data without requiring a
        // new complete arrival check or resetting the collector's retry state.
        var collecting=MailIndexState();collecting.discovered(now:now.addingTimeInterval(-300));collecting.prepare(accounts:accounts,now:now,calendar:calendar)
        _ = collecting.apply(MailBatch(messages:[kept],messageIDs:[1,2],nextOffset:1,complete:false,errors:[]),to:collecting.monitor("a")!.id,snapshot:original,now:now.addingTimeInterval(-300))
        collecting.failed("a",detail:"A message changed or moved",now:now)
        let checkpointEncoder=JSONEncoder();checkpointEncoder.outputFormatting=[.sortedKeys]
        let collectorBefore=try checkpointEncoder.encode(collecting)
        let cachedReview=MailReviewScope.collected(index:collecting,snapshot:original,excluded:[])
        assert(cachedReview.accountIDs == ["a"] && cachedReview.issues["a"] != nil && cachedReview.issues["b"] != nil,"Previously collected partial data stays eligible; uncollected accounts remain pending")
        assert(cachedReview.permits("a",index:collecting,snapshot:original,excluded:[]),"Existing collection failure does not prevent AI analysis")
        let collectorAfter=try checkpointEncoder.encode(collecting)
        assert(collectorAfter == collectorBefore,"Review capture must not resume, reset or advance the collector")
        assert(cachedReview.coverage(accounts:accounts).contains("last successful batch") && !cachedReview.coverage(accounts:accounts).contains("Freshly checked"),"Review coverage describes the collected cache honestly")
        let removedAccount=MailSnapshot(messages:original.messages,accounts:[accounts[1]],errors:[])
        assert(!cachedReview.permits("a",index:collecting,snapshot:original,excluded:["a"]) && !cachedReview.permits("a",index:collecting,snapshot:removedAccount,excluded:[]),"Collected mode retains account removal and permission guards")
        collecting.discovered(error:"discovery timeout",now:now)
        let discoveryCache=MailReviewScope.collected(index:collecting,snapshot:original,excluded:[])
        assert(discoveryCache.discoveryFailed && discoveryCache.accountIDs == ["a"],"Background discovery failure reports partial coverage without erasing collected mail")
        collecting.failed("a",detail:"body identity unavailable",now:now.addingTimeInterval(10))
        assert(!cachedReview.permits("a",index:collecting,snapshot:original,excluded:[]) && cachedReview.available(index:collecting,snapshot:original,excluded:[]).accountIDs.isEmpty,"A new body/read failure narrows in-flight analysis")
        let nextReview=MailReviewScope.collected(index:collecting,snapshot:original,excluded:[])
        assert(nextReview.accountIDs == ["a"] && nextReview.issues["a"] == "body identity unavailable","A later heartbeat may analyse retained headers with the failure disclosed")
        for _ in 0..<8 {collecting.failed("a",detail:"timeout",now:now)}
        let exhaustedBackoff=MailReviewScope.collected(index:collecting,snapshot:original,excluded:[])
        collecting.failed("a",detail:"timeout",now:now.addingTimeInterval(20))
        assert(!exhaustedBackoff.permits("a",index:collecting,snapshot:original,excluded:[]),"New failures still invalidate capture after the failure count saturates")
        collecting.resume();collecting.discovered(now:now.addingTimeInterval(30))
        _ = collecting.apply(empty,to:collecting.monitor("a")!.id,snapshot:original,now:now.addingTimeInterval(30))
        let completedCollection=exhaustedBackoff.available(index:collecting,snapshot:original,excluded:["b"])
        assert(completedCollection.accountIDs == ["a"] && !completedCollection.pending,"Completed background collection clears outdated coverage issues without widening captured account scope")
        assert(MailReviewScope.collected(index:oldIndex,snapshot:original,excluded:[]).accountIDs.isEmpty,"Legacy rows without a successful source receipt are not asserted available")
        let partial=try JSONDecoder().decode(MailDiscovery.self,from:Data(#"{"accounts":[{"id":"b","title":"Healthy"}],"errors":["Account a: Inbox unavailable"],"unavailableAccounts":[{"id":"a","title":"Unavailable"}],"accountErrors":{"a":"Account a: Inbox unavailable"}}"#.utf8))
        let prepared=try partial.collection(retaining:accounts)
        assert(Set(prepared.accounts.map(\.id)) == ["a","b"] && prepared.healthy.map(\.id) == ["b"] && prepared.failures["a"] != nil,"Partial account discovery keeps failed coverage while allowing the healthy lane")
        var partialIndex=MailIndexState();partialIndex.prepare(accounts:prepared.accounts,now:now,calendar:calendar)
        for (id,error) in prepared.failures {partialIndex.failed(id,detail:error,now:now)}
        assert(partialIndex.available("b",now:now) && !partialIndex.available("a",now:now) && partialIndex.monitors?.contains{$0.accountID == "a"} == true)
        let removedDiscovery=try MailDiscovery(accounts:[accounts[1]],errors:[]).collection(retaining:accounts)
        assert(removedDiscovery.accounts.map(\.id) == ["b"],"Successfully discovered account removal still takes effect")
        let legacyPartial=try MailDiscovery(accounts:[accounts[1]],errors:["Account a: Inbox unavailable"]).collection(retaining:accounts)
        assert(legacyPartial.accounts.count == 2 && legacyPartial.healthy.count == 1,"Legacy helper errors retain known failed accounts")
        print("PASS Mail monitoring: legacy migration, late-delivery overlap and arrival watermark, immutable interrupted cursors, bounded rotating audit/history, per-account retry isolation including discovery, offline catch-up, source removal and exact-range reconciliation")
    }
}
